UPDATE curriculum_repository_structure_nodes n
SET summary_de = v.summary_de, updated_at = now()
FROM (VALUES
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-erkenntnisse', 'Die Lernenden leiten aus komplexen Phänomenen Fragestellungen ab, führen eigene Untersuchungen durch und beurteilen die Aussagekraft von Daten. Sie reflektieren Grenzen, Vorläufigkeit und Subjektivität naturwissenschaftlicher Erkenntnisse, überarbeiten alternative Modelle und nutzen systematische Entscheidungsstrategien.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-oekosystem-mensch', 'Die Lernenden untersuchen den menschlichen Körper als Lebensraum mit Symbionten, Parasiten und Krankheitserregern sowie Immunabwehr und Impfung. Die Einheit erwähnt das Populationswachstum krankheitserregender Bakterien, ihre Anpassung an den menschlichen Wirt und die Entstehung von Antibiotikaresistenzen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/10/de-by-lp-bio-b10-vergangenheit-zukunft-mensch', 'Die Lernenden skizzieren die Geschichte des Lebens und ordnen den heutigen Menschen anhand anatomischer und molekularer Merkmale im natürlichen System der Lebewesen ein. Sie leiten aus Fossilfunden Hypothesen zur Evolution des Menschen ab und betrachten die kulturelle Evolution sowie die künftige Population des Menschen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12-13/de-by-lp-bio-b12-13-kompetenzrahmen', 'Kompetenzrahmen für die Qualifikationsphase. Die Lernenden bilden Hypothesen, planen und bewerten Untersuchungen und Modelle und reflektieren Kriterien naturwissenschaftlicher Erkenntnis wie Falsifizierbarkeit und Vorläufigkeit. Hinzu kommen proximate und ultimate Erklärung sowie Kommunikations- und Bewertungskompetenz.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-evolution-ea', 'Behandelt werden Stammbäume und Kladogramme, die Evolution des Menschen und die Synthetische Evolutionstheorie, angewandt auf die Artbildung unter Einbezug der Primaten, sowie die Koevolution. Die Lernenden befassen sich außerdem mit der kulturellen und sozialen Evolution des Menschen sowie mit den Grenzen und Gefahren menschlicher Eingriffe in evolutive Prozesse.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-evolution-ga', 'Die Lernenden erstellen Stammbäume und Kladogramme aus molekularen und anderen Merkmalen und vergleichen Ansätze zur Klassifikation der Lebewesen. Sie wenden die Synthetische Evolutionstheorie (Variation, Selektion, Drift, Isolation) an, um Artbildung und Biodiversität zu erklären, und beschreiben die Koevolution.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-genetik-ea', 'Die Lernenden befassen sich mit Speicherung und Auslesen der genetischen Information einschließlich alternativem Spleißen, mit der Regulation der Genaktivität einschließlich Epigenetik, mit DNA-Reparatur und Tumorentstehung. Behandelt werden Meiose, Mutationen und ihre Rolle in der Evolution, Gentechnik, Kreuzungen mit Genkopplung, epigenetische Vererbung und Stammbaumanalysen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-genetik-ga', 'Die Lernenden untersuchen, wie genetische Information gespeichert und ausgelesen, die Genaktivität reguliert und die DNA verdoppelt wird. Behandelt werden Meiose, Mutationen und ihre Rolle für Evolution und Biodiversität, Gentechnik, Mendelsche Kreuzungen, Stammbaumanalysen und ethische Aspekte der DNA-Analyse.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-verhaltensoekologie-ea', 'Ergänzt die Themen des Grundniveaus um Kommunikation und Signalfälschung und analysiert das Sozialverhalten von Primaten einschließlich des Menschen. Die Lernenden wägen innere und äußere Ursachen ab und gehen mit einseitigen biologischen Erklärungen menschlichen Verhaltens kritisch um.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/12/de-by-lp-bio-b12-verhaltensoekologie-ga', 'Die Lernenden erklären Verhalten über seine Wirkung auf die Fitness und wenden Methoden der Verhaltensökologie wie Kosten-Nutzen-Analyse und Optimalitätsmodelle an. Themen sind Kooperation und Altruismus, Aggression, Partnerwahl und elterliche Investition.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/13/de-by-lp-bio-b13-oekologie-ea', 'Ergänzt die Themen des Grundniveaus um quantitative Felddaten, r- und K-Strategien, das Räuber-Beute-Modell von Lotka und Volterra und die Abschätzung von Populationsgrößen. Die Lernenden untersuchen außerdem Wechselwirkungen zwischen Biomen, invasive Arten und die Auswirkung von Ökosystemveränderungen auf die Biodiversität.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/13/de-by-lp-bio-b13-oekologie-ga', 'Die Lernenden befassen sich mit Biotopen und Lebensgemeinschaften, Nahrungsnetzen, der Toleranz gegenüber abiotischen Faktoren, ökologischen Nischen und dem Populationswachstum. Anschließend behandeln sie Ökosystemleistungen, den Wert der Biodiversität und Wertkonflikte zwischen wirtschaftlichen und ökologischen Ansprüchen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/5/de-by-lp-bio-nut5-erkenntnisse', 'Die Lernenden lernen die Schritte einer naturwissenschaftlichen Untersuchung, grundlegende Labor- und Freilandtechniken sowie das Mikroskopieren kennen und erkennen, dass sich wissenschaftliches Wissen im Lauf der Zeit verändert. Sie lernen außerdem, was ein Modell ist und was es weglässt, und wie man Ergebnisse mit Tabellen und Diagrammen dokumentiert und erklärt.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-erkenntnisse', 'Baut auf den Untersuchungsschritten auf und ergänzt Variablen, Konstanten und Kontrollversuche, Fehlerquellen, strukturiertes Beobachten und das Bestimmen von Arten. Die Lernenden vergleichen Modelle mit dem, was sie darstellen, und beurteilen einfache Quellen, wobei sie beschreibende von bewertenden Aussagen trennen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-verwandtschaft-evolution', 'Die Lernenden ordnen Wirbeltiere anhand charakteristischer Merkmale in Klassen ein und lernen ein vereinfachtes Evolutionsmodell kennen, in dem unterschiedliche Merkmale Vorteile bringen können. Sie vergleichen die Züchtung durch den Menschen mit natürlichen Evolutionsprozessen und beurteilen die Haltung von Heim- und Nutztieren.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/6/de-by-lp-bio-nut6-wirbeltiere-angepasstheit', 'Die Lernenden vergleichen Wirbeltierklassen hinsichtlich ihrer Angepasstheiten bei Fortbewegung, Ernährung und Energienutzung, Fortpflanzung und Sinnesleistungen. Themen sind Temperaturregulation, Signale innerhalb einer Art, elterliche Investition sowie die Unterscheidung artspezifischer Merkmale von Merkmalen der übergeordneten Gruppe.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/8/de-by-lp-bio-b8-erkenntnisse', 'Die Lernenden formulieren biologische Fragestellungen, planen einfache Untersuchungen und interpretieren Daten unter Berücksichtigung möglicher Fehlerquellen. Sie erörtern, wie wissenschaftliches Wissen wächst und was Modelle zeigen können und was nicht, und wägen Folgen menschlichen Handelns für Nachhaltigkeit und Gesundheit ab.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/8/de-by-lp-bio-b8-verhalten', 'Die Lernenden beobachten und vergleichen einfache Verhaltensweisen, auch in Attrappenversuchen, als Ergebnis innerer Faktoren und auslösender Reize. Sie beurteilen anhand von Beobachtungsdaten, ob ein Verhalten überwiegend angeboren oder erlernt ist, und planen Experimente zur klassischen und operanten Konditionierung.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-erkenntnisse', 'Die Lernenden planen hypothesengeleitete Untersuchungen, vergleichen Lebewesen, um Ursachen für Ähnlichkeiten zu erschließen, und beurteilen die Aussagekraft von Daten. Sie beschreiben Merkmale wissenschaftlicher Erkenntnis, zum Beispiel in der Evolutionsforschung, und entwickeln alternative Modelle, wobei sie Stärken und Grenzen benennen.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-evolution', 'Die Lernenden beschreiben die Geschichte des Lebens als fortdauernde, durch wissenschaftliche Belege gestützte Evolution. Sie erklären, wie eine heutige Art durch genetische Variabilität, natürliche Selektion und geografische Isolation entstanden ist, und erklären Angepasstheiten als Selektionsvorteile.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-genetik', 'Die Lernenden verknüpfen DNA-Struktur, Proteinbiosynthese und Merkmale und behandeln dann Chromosomenorganisation, Replikation und Zellzyklus. Sie erklären Meiose und Befruchtung als Quellen genetischer Vielfalt sowie Genommutationen wie die Trisomie 21 und wägen ethische Aspekte von Diagnostik und Gentechnik ab.'),
  ('germany-curriculum-repository', 'DE-BY/biologie/gymnasium/online-edition-of-the-lehrplanplus-as-di/9/de-by-lp-bio-b9-wirbellose', 'Die Lernenden vergleichen Insekten mit Wirbeltieren und anderen Wirbellosen in Fortbewegung, Stoffwechsel, Fortpflanzung und Nervensystem und beschreiben die vorgefundene Vielfalt als evolutive Angepasstheit. Themen sind Metamorphose, Mundwerkzeuge, Sinne sowie Signale wie Mimikry und Pheromone.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/10/de-by-lp-inf-inf10-datenmodellierung-relationale-datenbanken', 'Die Lernenden erstellen aus Praxisfällen Datenmodelle mit mehreren Klassen, überführen sie in relationale Modelle mit Schlüsseln, fragen verknüpfte Tabellen mit SQL ab und beurteilen Redundanz und Anomalien in gespeicherten Daten.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/10/de-by-lp-inf-inf10-oo-modellierung-programmierung', 'Die Lernenden verwenden Reihungen (Arrays), setzen Beziehungen zwischen Klassen über Referenzen um, wenden Kapselung und Polymorphie an und verwalten Sammlungen gleichartiger Objekte in einer kleinen Anwendung.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/10/de-by-lp-inf-inf10-projekt', 'Die Lernenden planen, modellieren, implementieren, testen und dokumentieren im Team eine Datenbank oder ein objektorientiertes Programm für ein Szenario wie ein Buchungssystem oder ein einfaches Spiel.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-ntg-codierung-verschluesselung', 'Die Lernenden erklären, wie Information codiert und mit Prüfsummen abgesichert wird, wandeln Zahlen zwischen Binär- und Hexadezimaldarstellung um und untersuchen symmetrische und asymmetrische Verschlüsselung, Brute-Force-Angriffe und digitale Signaturen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-ntg-graphen', 'Die Lernenden modellieren vernetzte Strukturen als Graphen, implementieren einen Graphen mit einer Adjazenzmatrix und arbeiten mit der Breitensuche und dem Dijkstra-Algorithmus für kürzeste Wege.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-ntg-kuenstliche-intelligenz', 'Die Lernenden diskutieren Definitionen künstlicher Intelligenz, erklären ein Verfahren des maschinellen Lernens wie nächste Nachbarn oder Entscheidungsbäume, untersuchen den Einfluss der Trainingsdaten auf die Ergebnisse, beschreiben und implementieren ein künstliches Neuron und wägen gesellschaftliche Chancen und Risiken ab.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-ntg-netzwerke-internet', 'Die Lernenden beschreiben den Aufbau des Internets und die Adressierung von Geräten, erklären schichtenbasierte Kommunikation und Protokolle und beschreiben die Client-Server-Interaktion in Webanwendungen samt ihren Risiken.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-ntg-vertiefung', 'Die Lernenden lösen ein weiteres Problem mit Bezug zu einer der ersten vier Einheiten, gegebenenfalls mit Projektmethoden, ohne Inhalte der Jahrgangsstufen 12 und 13 vorwegzunehmen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-spaet-algorithmik', 'Die Lernenden entwerfen und implementieren einfache Algorithmen mit Variablen, Kontrollstrukturen und Funktionsaufrufen in einer visuellen oder textbasierten Sprache, nutzen für Aufgaben wie die Suche nach einem Maximum eine Liste oder ein Array und testen ihre Programme systematisch.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-spaet-codierung-verschluesselung', 'Die Lernenden erklären, wie Information codiert und mit Prüfsummen abgesichert wird, wandeln Zahlen zwischen Binär- und Hexadezimaldarstellung um und untersuchen symmetrische und asymmetrische Verschlüsselung, Brute-Force-Angriffe und digitale Signaturen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-spaet-kuenstliche-intelligenz', 'Die Lernenden diskutieren Definitionen künstlicher Intelligenz, erklären die Idee eines Verfahrens des maschinellen Lernens wie nächste Nachbarn oder Entscheidungsbäume, simulieren ein künstliches Neuron und wägen gesellschaftliche Chancen und Risiken des KI-Einsatzes ab.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/11/de-by-lp-inf-inf11-spaet-netzwerke-internet', 'Die Lernenden beschreiben den Aufbau des Internets und die Adressierung von Geräten, erklären schichtenbasierte Kommunikation und Protokolle und beschreiben die Client-Server-Interaktion in Webanwendungen samt ihren Risiken.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-baeume', 'Die Lernenden modellieren geordnete Binärbäume, schreiben rekursive Algorithmen zum Durchlaufen, Einfügen und Suchen, vergleichen den Suchaufwand mit verketteten Listen und lernen Einsatzmöglichkeiten anderer Baumarten wie der Huffman-Bäume kennen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-betriebssysteme-nebenlaeufigkeit', 'Die Lernenden erklären Aufgaben und Sicherheitsmechanismen von Betriebssystemen, vergleichen Scheduling-Strategien, modellieren gemeinsam genutzte Betriebsmittel und Verklemmungen (Deadlocks) und implementieren synchronisierte nebenläufige Prozesse mit Monitoren oder Semaphoren.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-funktionsweise-rechner', 'Die Lernenden vergleichen Rechnerkomponenten anhand des Von-Neumann-Modells, stellen ganze Zahlen im Zweierkomplement dar, bauen Logikschaltungen aus Gattern, erklären eine Registermaschine und schreiben einfache Assemblerprogramme dafür.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-informationssicherheit', 'Die Lernenden analysieren ein Informationssystem im Hinblick auf die wichtigsten Schutzziele, beschreiben Bedrohungskategorien und Angriffsszenarien, erklären Schutzmaßnahmen samt ihren Grenzen und diskutieren Fragen wie die Offenlegung von Schwachstellen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-listen', 'Die Lernenden modellieren einfach verkettete Listen mit dem Entwurfsmuster Kompositum, schreiben rekursive Methoden zum Einfügen, Löschen und Suchen, lesen Sequenzdiagramme und bauen Stapel und Schlangen auf.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-rekursion', 'Die Lernenden analysieren und vergleichen rekursive und iterative Algorithmen, implementieren rekursive Lösungen wie den größten gemeinsamen Teiler und arbeiten mit der Tiefensuche in Graphen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ea-softwareentwicklung-projekt', 'Die Lernenden beurteilen Softwarequalität und Benutzbarkeit, entwerfen einfache grafische Oberflächen, vergleichen das Wasserfallmodell mit agilen Methoden, nutzen Entwurfsmuster, testen und refaktorisieren Code und führen ein Softwareprojekt im Team durch.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-binaerbaeume', 'Die Lernenden modellieren geordnete Binärbäume, schreiben rekursive Algorithmen zum Durchlaufen, Einfügen und Suchen, setzen sie in einer objektorientierten Sprache um und vergleichen den Suchaufwand mit verketteten Listen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-informationssicherheit', 'Die Lernenden analysieren ein Informationssystem im Hinblick auf die wichtigsten Schutzziele, beschreiben Bedrohungskategorien und Angriffsszenarien, erklären Schutzmaßnahmen samt ihren Grenzen und diskutieren Fragen wie die Offenlegung von Schwachstellen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-listen', 'Die Lernenden modellieren einfach verkettete Listen mit dem Entwurfsmuster Kompositum, schreiben rekursive Methoden zum Einfügen, Löschen und Suchen, lesen Sequenzdiagramme und bauen Stapel und Schlangen auf.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-nebenlaeufige-prozesse', 'Die Lernenden analysieren parallele Aktivitäten, die gemeinsame Betriebsmittel nutzen, modellieren die Nutzung von Betriebsmitteln und Verklemmungen, beschreiben Threads mit Sequenzdiagrammen und implementieren einfache nebenläufige Programme, die mit einem Monitor synchronisiert sind.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-rekursion', 'Die Lernenden analysieren und vergleichen rekursive und iterative Algorithmen, implementieren rekursive Lösungen wie den größten gemeinsamen Teiler und arbeiten mit der Tiefensuche in Graphen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-ga-softwareentwicklung-projekt', 'Die Lernenden verwenden Bibliotheksklassen und ihre Dokumentation, erklären die Idee des Model-View-Controller-Musters, testen und refaktorisieren vorgegebene Software, vergleichen das Wasserfallmodell mit einem agilen Modell und führen ein Softwareprojekt im Team durch.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-graphen', 'Die Lernenden modellieren vernetzte Strukturen als Graphen, implementieren einen Graphen mit einer Adjazenzmatrix und arbeiten mit der Tiefensuche und dem Dijkstra-Algorithmus für kürzeste Wege.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-informationssicherheit', 'Die Lernenden wägen Datenschutzregeln gegen persönliche und öffentliche Interessen ab, analysieren ein Informationssystem im Hinblick auf die wichtigsten Schutzziele, beschreiben Bedrohungen und erklären Schutzmaßnahmen samt ihren Grenzen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-listen', 'Die Lernenden modellieren einfach verkettete Listen, entwickeln rekursive Algorithmen zum Einfügen, Löschen und Durchlaufen von Elementen und implementieren die Listenstruktur in einer objektorientierten Sprache.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-oo-modellierung-programmierung', 'Die Lernenden abstrahieren Objekte zu Klassen, deklarieren und implementieren Methoden, modellieren und implementieren Beziehungen zwischen Klassen durch Referenzen, verwenden Felder (Arrays) und bauen Generalisierungshierarchien mit Vererbung und Polymorphie auf.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-rekursion', 'Die Lernenden analysieren und vergleichen rekursive und iterative Algorithmen und implementieren rekursive Lösungen, etwa für den größten gemeinsamen Teiler oder die Türme von Hanoi.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/12/de-by-lp-inf-inf12-spaet-softwareentwicklung-projekt', 'Die Lernenden verwenden Bibliotheksklassen, zum Beispiel für eine grafische Benutzeroberfläche, vergleichen das Wasserfallmodell mit einem agilen Modell und führen in einem Team ein Softwareprojekt zu einer einfachen praktischen Aufgabe durch.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-hierarchische-informationsstrukturen', 'Die Lernenden ordnen Informationen hierarchisch, zeichnen Baumdiagramme, analysieren ein Dateisystem als Objekte und Klassen und nutzen Ordner und Pfade, um Dateien zu organisieren und aufzufinden.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-informationsdarstellung', 'Die Lernenden betrachten Grafik-, Text- und Multimediadokumente als Sammlungen von Objekten mit Eigenschaften, modellieren sie mit Klassen- und Objektdiagrammen, vergleichen Vektor- und Pixelgrafiken und nutzen Standardsoftware, um Informationen übersichtlich darzustellen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/6/de-by-lp-inf-nt6-projekt-multimediapraesentation', 'Innerhalb eines vorgegebenen Zeitrahmens erstellen die Lernenden eine Multimediapräsentation zu einem vorgegebenen Thema, wenden Qualitätskriterien für die Foliengestaltung an und beachten beim Zusammenstellen der Inhalte grundlegende Regeln des Urheberrechts.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-ablaeufe-durch-algorithmen', 'Die Lernenden analysieren Alltagsprobleme, entwerfen Algorithmen aus Folgen, bedingten Anweisungen und Schleifen und führen einfache Algorithmen mit einem geeigneten Programmierwerkzeug aus.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-chancen-risiken-digitaler-kommunikation', 'Die Lernenden wägen Chancen und Risiken digitaler Kommunikation für den Einzelnen und die Gesellschaft ab, schützen ihre eigenen Geräte und lernen Regeln zu Persönlichkeitsrechten und Datenschutz im Austausch im Netz kennen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-projekt', 'Im Team und innerhalb einer festen Zeit erstellen die Lernenden einen Hypertext zu einem vorgegebenen Thema oder lösen eine algorithmische Aufgabe, etwa ein Problem des Physical Computing, und halten ihre Zwischenergebnisse schriftlich fest.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/7/de-by-lp-inf-nt7-vernetzte-informationsstrukturen', 'Die Lernenden modellieren Hypertext als verknüpfte Objekte und Graphen, erstellen einen Hypertext mit einem einfachen Editor, recherchieren im Internet mit kritischem Blick auf die Qualität der Quellen und beschreiben, wie Dokumente zwischen Clients und Servern übertragen werden.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-datenmodellierung-datenbanksysteme', 'Die Lernenden modellieren Datenbestände mit Objekten und Klassen, überführen das Modell in Tabellenschemata eines Datenbanksystems und formulieren einfache SQL-Abfragen, um Informationen aus einer Tabelle abzurufen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-datenschutz', 'Die Lernenden beurteilen Datenschutzregelungen im Verhältnis zu Persönlichkeitsrechten sowie zu wirtschaftlichen oder öffentlichen Interessen, reflektieren ihre eigene Nutzung datenbankgestützter Online-Dienste und bewerten Chancen und Risiken von Data-Mining in großem Umfang.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-funktionen-datenfluesse-tabellenkalkulation', 'Die Lernenden beschreiben Datenverarbeitungsschritte als Funktionen, zeichnen Datenflussdiagramme, verketten Funktionen und setzen sie als Formeln in der Tabellenkalkulation um, um praktische Aufgaben zu lösen.'),
  ('germany-curriculum-repository', 'DE-BY/informatik/gymnasium/online-edition-on-lehrplanplus-bayern-de/9/de-by-lp-inf-inf9-oo-modellierung-programmierung', 'Die Lernenden abstrahieren Objekte zu Klassen, deklarieren Klassen mit Attributen und Methoden in einer objektorientierten Sprache, setzen mit Zuweisungen und Kontrollstrukturen Algorithmen um und bauen einfache Vererbungshierarchien auf.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb1-genetik', 'Die Schülerinnen und Schüler verknüpfen Genotyp und Phänotyp, unterscheiden Mutation von Modifikation und arbeiten mit Mendelschen Kreuzungen, Chromosomen, DNA und Proteinbiosynthese. Sie behandeln Humangenetik wie Stammbäume und Erbkrankheiten, anschließend Züchtung und Gentechnik mit ihren ethischen Fragen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb2-entstehung-der-artenvielfalt', 'Die Schülerinnen und Schüler lernen historische Vorstellungen von Evolution (Linné, Lamarck, Darwin) und das Zusammenwirken von Mutation, Rekombination, Selektion und Isolation kennen, dazu Art- und Populationskonzepte. Anpassungstrends und Belege wie Fossilien und Homologien werden untersucht.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-lb3-stammesgeschichte-des-menschen', 'Die Schülerinnen und Schüler vergleichen den Menschen mit den Menschenaffen in Anatomie und Verhalten und verfolgen die Evolution des Menschen von frühen Hominini bis zum Homo sapiens. Sie betrachten biologische und kulturelle Evolution, Sozialverhalten und die gemeinsame Biologie aller heutigen Menschen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-wb2-entstehung-des-lebens', 'Eine Wahleinheit zu konkurrierenden Hypothesen über die Entstehung des Lebens: die frühe Atmosphäre, chemische und biologische Evolution und Schöpfungserzählungen, mit den Arbeiten von Oparin, Miller und Fox.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/10/de-sn-lp-bio-bio-k10-wb3-lernen-und-gedaechtnis', 'Eine Wahleinheit, die das Wissen über das Nervensystem auf das Lernen anwendet: Kurzzeit- und Langzeitgedächtnis, Lernstrategien und Problemlösen sowie das Zusammenwirken von Großhirn und Kleinhirn.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/11/de-sn-lp-bio-bio-gk11-lb3-oekologie-und-nachhaltigkeit', 'Die Lernenden untersuchen ein naturnahes Landökosystem: Toleranzbereiche, Anpassung an abiotische Faktoren, Konkurrenz, Nischen, Nahrungsnetze und Energiefluss. Sie beurteilen Schädlingsbekämpfung, Monokulturen, Klimawandel und Schutzmaßnahmen und planen eine Exkursion mit Messungen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/11/de-sn-lp-bio-bio-lk11-lb3-oekologie-und-nachhaltigkeit', 'Erweitert den Grundkurs um Populationswachstum (dichteabhängige Faktoren, r- und K-Strategien, exponentielles und logistisches Wachstum, Lotka-Volterra-Regeln), Stoffkreisläufe und Monokulturen. Die Lernenden wägen Ökosystemmanagement ab und führen eine Exkursion mit Dokumentation durch.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-lb1-genetik', 'Die Lernenden wenden die Mendelschen Regeln auf ungekoppelte Vererbung an und verfolgen, wie Genmutationen Erbkrankheiten verursachen. Sie lernen Verfahren wie PCR, Sequenzierung und Gelelektrophorese kennen, anschließend die somatische Gentherapie sowie die Ethik von Therapie und Embryonendiagnostik.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-lb3-biodiversitaet', 'Die Lernenden nutzen das populationsgenetische Artkonzept und das Zusammenspiel von Mutation, Rekombination, Selektion, Isolation, Migration, Drift und Koevolution. Sie untersuchen proximate und ultimate Ursachen von Verhalten, molekulare Belege und Stammbäume und grenzen die Evolutionstheorie von Sichtweisen außerhalb der Wissenschaft ab.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-gk12-wb4-verhaltensbiologisches-praktikum', 'Ein Wahlpraktikum, in dem die Lernenden Beobachtungen und Experimente zum Verhalten von Tieren oder Menschen planen, etwa zu Aggression, Revier und Lernen, mit Tieren wie Grillen, Kleinsäugern oder Kampffischen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb1-genetik', 'Die Lernenden verknüpfen die Genetik mit Konstanz und Variabilität über Mutation, Rekombination, Meiose und gekoppelte Vererbung. Sie befassen sich mit humangenetischen Verfahren und Diagnostik, Krebsgenen, Gentransfer bei Bakterien und Viren, Stammzellen und Gentherapie und diskutieren die Ethik.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb3-verhalten-von-tier-und-mensch', 'Die Lernenden lernen Methoden der Verhaltensbiologie wie Ethogramme und unvoreingenommene Beobachtung kennen sowie die Ursachen von Verhalten (endogen und exogen, proximat und ultimat). Kosten-Nutzen-Analyse und Fitness erklären den Anpassungswert. Das Sozialverhalten von Primaten, Entwicklung, Kommunikation und Fortpflanzung dienen als Anwendungen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-lb4-biodiversitaet', 'Die Lernenden wenden die Synthetische Evolutionstheorie auf Progression und Spezialisierung an, einschließlich adaptiver Radiation, Drift, Zufall und Koevolution. Sie beurteilen den Sozialdarwinismus und Goulds Theorie, nutzen molekulare Belege und Stammbäume und behandeln die Evolution des Menschen und die kulturelle Evolution.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-wb2-evolution-des-stoffwechsels', 'Wahlbereich, in dem das Wissen über den Stoffwechsel auf die Evolution der Ernährungstypen angewendet wird: Protobionten und Eobionten, Prokaryoten- und Eukaryotenzellen, Endosymbiontenhypothese, Chemosynthese und Fotosynthese, Gärung und Atmung.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/12/de-sn-lp-bio-bio-lk12-wb4-verhaltensbiologisches-praktikum', 'Wahlbereich in Form eines Praktikums, in dem die Lernenden Beobachtungen und Experimente zum Verhalten von Tieren oder Menschen planen, zum Beispiel zu Aggression, Revier und Lernen. Dabei nutzen sie digitale Medien und Tiere wie Grillen, Kleinsäuger oder Kampffische.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb1-merkmale-des-lebens', 'Die Lernenden erhalten einen ersten Einblick in das Fach Biologie und in die Arbeitsweisen von Biologinnen und Biologen: Beobachten, Untersuchen und Vergleichen. Sie lernen ausgewählte Merkmale des Lebens kennen und grenzen Lebewesen von unbelebten Objekten ab.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb2-fische', 'Die Lernenden lernen die Vielfalt der Fische anhand von etwa sechs heimischen Arten kennen. Sie behandeln Körperform, Schuppen und Kiemen als Angepasstheiten an das Leben im Wasser, beschäftigen sich mit Fortpflanzung und Nahrungsketten und bewerten Maßnahmen zum Schutz der Fischbestände.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb5-voegel', 'Die Lernenden verschaffen sich einen Überblick über heimische Vögel und bringen Körperform, Skelett, Lunge und Schnabelform mit Flug und Nahrungserwerb in Zusammenhang. Sie betrachten außerdem Verhaltensweisen wie Revierverhalten, Balz, Gesang und Brutpflege und erörtern Möglichkeiten zum Schutz heimischer Vögel.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb6-saeugetiere', 'Die Lernenden vergleichen wild lebende Säugetiere und Haussäugetiere, auch im Hinblick darauf, wie Rassen aus Wildtieren gezüchtet wurden. Sie beobachten Kommunikation, Zusammenarbeit, Rangordnung und Revierverhalten und setzen Gliedmaßenskelette, Gebisse und Lungen in Beziehung zu Lebensraum und Ernährung.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-lb7-systematisierung', 'Die Lernenden führen ihr Wissen über die Wirbeltiergruppen zusammen, indem sie Atmungsorgane, Körperbedeckung und Fortpflanzung im Zusammenhang mit dem Lebensraum vergleichen. Die Einheit bereitet den Entwicklungsgedanken vor.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/5/de-sn-lp-bio-bio-k5-wb2-kriechtiere-vergangener-zeiten', 'Wahlbereich, in dem die Lernenden unter Nutzung digitaler Medien einen Vortrag über Dinosaurier als ausgestorbene Kriechtiere vorbereiten. Sie greifen dabei auf Fossilien und grundlegende Paläontologie zurück.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb2-wirbellose-tiere', 'Die Lernenden verschaffen sich einen Überblick über die Gruppen der Wirbellosen und wenden die Themen Angepasstheit und Fortpflanzung auf den Regenwurm und auf Insekten an, einschließlich Metamorphose und Mundwerkzeugen. Die Honigbiene zeigt einen Insektenstaat mit Arbeitsteilung und Kommunikation. Parasiten werden kurz angesprochen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb3-systematisierung', 'Die Lernenden vergleichen Gruppen der Wirbellosen und der Wirbeltiere nach Skelett, Atmungsorganen und Fortpflanzung und verknüpfen dabei Bau und Funktion mit der Angepasstheit an den Lebensraum.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/6/de-sn-lp-bio-bio-k6-lb4-wald-lebensgemeinschaft', 'Die Lernenden untersuchen die Schichten eines naturnahen Mischwaldes und die darin lebenden Organismen, verfolgen Nahrungsnetze zwischen Pflanzen, Tieren und Pilzen und lernen die Waldschäden in Sachsen sowie Maßnahmen zum Schutz der Wälder kennen.'),
  ('saxony-curriculum-repository', 'DE-SN/biologie/gymnasium/2004-ueberarbeitung-2025-portal-edition/9/de-sn-lp-bio-bio-k9-lb2-zusammenhaenge-im-oekosystem', 'Ein See dient als Beispielökosystem: Nahrungsnetze, ökologische Nischen, Sukzession, Toleranz gegenüber Licht und Temperatur sowie Beziehungen innerhalb einer Art und zwischen Arten wie Konkurrenz, Symbiose, Parasitismus und Räuber-Beute-Beziehung. Kohlenstoffkreislauf, Klimawandel und menschlicher Einfluss gehören dazu.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb1-algorithmen', 'Die Lernenden setzen grundlegende Algorithmenstrukturen in einer textbasierten Programmiersprache um, mit Syntax und Semantik, Datentypen, Variablen und zusammengesetzten Bedingungen. Sie lernen die Modularisierung mit Unterprogrammen und Bibliotheken kennen und betrachten automatisierte Entscheidungen wie autonomes Fahren und Gesichtserkennung.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb2-sprachen', 'Die Lernenden lernen reguläre Sprachen und reguläre Ausdrücke zum Suchen, Ersetzen und Validieren von Daten kennen. Außerdem strukturieren sie Dokumente mit Auszeichnungssprachen wie HTML, XML, LaTeX und Markdown und behandeln dabei Überschriften, Verweise und Ausgabeformate.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-lb3-komplexaufgabe', 'Die Lernenden planen und führen ein Teamprojekt durch, das Inhalte der Klassenstufen 9 und 10 verbindet, zum Beispiel den Bau und das Testen einer KI, einer Webanwendung, eines Chatbots oder eines Client-Server-Dienstes.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb1-3d-computergrafik', 'Wahlbereich zur Darstellung räumlicher Objekte mit Software, einschließlich des Exports für den 3D-Druck sowie der Grundideen von Rendering und Raytracing.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb2-zeitabhaengige-medien', 'Wahlbereich zu Audio und Video: Speicherung und Codierung, Abtastung, Einzelbilder und Kompression mit Videocodecs.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/10/de-sn-lp-inf-inf-k10-wb3-robotik', 'Wahlbereich zur Funktionsweise eines Robotersystems: Einplatinencomputer, Sensoren und Aktoren.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb1-technische-informatik', 'Die Lernenden beschäftigen sich mit Binär- und Hexadezimalzahlen, Zahlenformaten, Zeichencodes und boolescher Algebra und wenden diese mit Simulationssoftware auf Schaltnetze an. Außerdem behandeln sie die Herstellung von Mikrochips, Rechnerarchitektur, Speichersysteme und den nachhaltigen Einsatz von Hardware.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb2-algorithmierung-und-programmierung', 'Die Lernenden erweitern den Algorithmusbegriff, setzen strukturierte Datentypen und Unterprogramme um, lernen objektorientierte Konzepte wie Vererbung und Polymorphie kennen und behandeln die Rekursion. Sie programmieren Lösungen für komplexe Probleme und untersuchen Effizienz, Komplexität und die Grenzen der Berechenbarkeit.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb3-rechnernetze', 'Die Lernenden beschäftigen sich mit Netzwerkmedien, Topologien, Paketvermittlung und TCP/IP, modellieren Netze mit Simulationen oder Einplatinencomputern und lernen Adressierung, Routing und Namensauflösung kennen. Sicherheitsmaßnahmen wie TLS, VPN und Zwei-Faktor-Authentifizierung werden angewendet.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb4-informationssicherheit', 'Die Lernenden lernen die Schutzziele der Informationssicherheit, Prinzipien der symmetrischen und asymmetrischen Kryptografie, digitale Signaturen und Methoden der Datensicherung kennen und beziehen Stellung zu einer aktuellen Frage des Datenschutzes.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb5-datenmanagement', 'Die Lernenden lernen Einsatzbereiche von Open Data und Big Data, den Lebenszyklus von Daten sowie das relationale Modell mit ER-Diagrammen kennen, schreiben SQL-Abfragen und visualisieren die Ergebnisse. Sie wenden maschinelles Lernen auf die Datenanalyse an und erörtern Verzerrungen, Verlässlichkeit sowie den Unterschied zwischen Korrelation und Kausalität.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb6-sprachen-und-automaten', 'Die Lernenden vergleichen natürliche und formale Sprachen, arbeiten mit formalen Grammatiken, entwerfen endliche Automaten und überführen bei regulären Sprachen Grammatiken in Automaten und umgekehrt. Sie wägen Chancen und Risiken der automatisierten Sprachverarbeitung ab, etwa bei Sprachassistenten und Bots.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb7-informatisches-projekt', 'Die Lernenden lernen Techniken des Projektmanagements kennen (klassisches oder agiles Vorgehen, Kostenplanung, Stakeholderanalyse, Dokumentation, Reflexion) und wenden sie in einem Projekt an, das Inhalte der anderen Lernbereiche aufgreift.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8a-kuenstliche-intelligenz', 'Die Lernenden definieren künstliche Intelligenz (schwache, starke, Superintelligenz), verschaffen sich einen Überblick über symbolische KI und maschinelles Lernen und wenden Verfahren wie Regression, Entscheidungsbäume, neuronale Netze, genetische Algorithmen, Clustering und Q-Learning an. Sie beurteilen gesellschaftliche Auswirkungen, darunter den Umgang mit subjektiven Modellen als objektiven Tatsachen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8b-softwareentwicklung', 'Die Lernenden lernen Grundlagen der Softwarearchitektur (Model-View-Controller, Monolith) kennen, vergleichen klassische (Wasserfall, V-Modell) und agile Entwicklung (Sprints, Prototyping) und setzen mit einer Methode eine Lösung um.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-lb8c-prozessautomatisierung', 'Die Lernenden lernen Modelle des Steuerns und Regelns kennen (offene Steuerkette, Regelkreis, Messen, Steuern, Regeln) und wenden sie mit Mikrocontrollern, Sensoren und Aktoren in Anwendungsfeldern wie dem Internet der Dinge und dem Smart Home an.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb1-3d-modellierung', 'Wahlbereich zur geometrischen Modellierung einfacher Körper (Ansichten, Schnitte, Z-Buffer) und zur Herstellung von 3D-Objekten.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb2-quanteninformatik', 'Wahlbereich, in dem Quanteninformation von klassischer Information abgegrenzt wird (Quantenzustände, Qubits, Superposition, Verschränkung). Er behandelt Quantencomputer und Quantenkryptografie und erörtert die Auswirkungen auf die Informationssicherheit.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb3-wirtschaftsinformatik', 'Wahlbereich zu digitalen Gütern und Netzwerkökonomie (Skaleneffekte, Fixkosten, Netzwerkeffekte, Plattformökonomie, Lock-in) sowie zu Finanzierungsmodellen für Software wie Abonnements, Werbung und Open Source.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-gk-wb4-informatik-und-oekologie', 'Wahlbereich zur ökologischen Seite der Informatik: Energieverbrauch des Internets, Algorithmen und Hardwareherstellung, Ressourcenverbrauch und geplante Obsoleszenz sowie Green IT mit nachhaltiger Nutzung von Geräten.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb1-technische-informatik', 'Erweitert den Grundkurs um Zahlenformate, boolesche Algebra und ihre Vereinfachungsgesetze, Analyse und Synthese von Schaltnetzen einschließlich Halb- und Volladdierer, Rechnerarchitektur sowie einen Vergleich kommerzieller und quelloffener Systemsoftware.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb10-kuenstliche-intelligenz', 'Die Lernenden beschäftigen sich mit den Grundlagen der KI, mit symbolischer KI wie Expertensystemen und Wissensgraphen sowie mit maschinellem Lernen (überwachtes, unüberwachtes und bestärkendes Lernen). Sie bauen eine KI, indem sie Daten sammeln und einen Algorithmus auswählen und testen, und beurteilen Erklärbarkeit, Verzerrungen und gesellschaftliche Auswirkungen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb11-informatisches-projekt', 'Die Lernenden lernen Projektmanagement kennen (Kostenplanung, Stakeholderanalyse, Risikomanagement, klassische und agile Vorgehensweisen) und führen ein Projekt durch, das Inhalte der anderen Lernbereiche verbindet. Dabei nutzen sie Werkzeuge wie Kanban-Boards, Sprints und Gantt-Diagramme.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12a-quanteninformatik', 'Die Lernenden grenzen Quanteninformation von klassischer Information ab (Quantenzustände, Qubits, Hadamard-Gatter), lernen, wie Superposition und Verschränkung der Informationsverarbeitung dienen, verschaffen sich einen Überblick über Quantencomputer, Quantennetzwerke und Quantenkryptografie und erörtern die Auswirkungen auf die Informationssicherheit.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12b-3d-modellierung', 'Die Lernenden lernen, wie 3D-Objekte digital mit einem kartesischen Koordinatensystem, Vektoren und CAD-Software dargestellt werden, modellieren einfache Körper und lernen Fertigungsverfahren wie 3D-Druck, CNC-Fräsen und Lasergravur kennen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12c-prozessautomatisierung', 'Die Lernenden lernen Modelle des Steuerns und Regelns kennen und wenden sie auf informatische Systeme mit Mikrocontrollern, Sensoren, Aktoren, Robotikbaukästen und Smart-Home-Szenarien an.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb12d-webtechnologien', 'Die Lernenden lernen, wie Websysteme funktionieren (Hypertext, Browser, Client-Server), erstellen statische Seiten mit einer Auszeichnungssprache und dynamische Webanwendungen mit einer Skriptsprache, binden eine Datenbank an und beschäftigen sich mit grundlegenden Bedrohungen und Sicherheitsmechanismen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb2-datenstrukturen-und-algorithmen', 'Die Lernenden beschäftigen sich mit komplexen Datenstrukturen (Bäume, Graphen, Listen, Stapel und Warteschlangen), setzen strukturierte und dynamische Datentypen um und nutzen Strategien wie Teile und herrsche, Backtracking und Traversierung. Sie wenden Rekursion sowie Such- und Sortierverfahren an und lernen, wie große und sich ändernde Datenmengen verarbeitet werden.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb3-komplexitaet-und-berechenbarkeit', 'Die Lernenden beurteilen die Effizienz und Komplexität von Algorithmen anhand von Komplexitätsklassen und Zeitaufwand und lernen Grenzen der Berechenbarkeit kennen, etwa das Halteproblem, P- und NP-Probleme, Näherungslösungen sowie entscheidbare und unentscheidbare Mengen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb4-programmierparadigmen', 'Die Lernenden vergleichen imperative, objektorientierte, funktionale und logische Programmierung, ordnen Programmiersprachen ein, lernen objektorientierte Konzepte wie Aggregation, Vererbung und Polymorphie kennen und lösen ein Problem objektorientiert.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb5-softwareentwicklung', 'Die Lernenden lernen Grundlagen der Softwarearchitektur kennen, vergleichen klassische und agile Entwicklung, begegnen Versionsverwaltungssoftware und wenden Methoden der agilen Entwicklung an.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb6-sprachen-und-automaten', 'Die Lernenden vergleichen natürliche und formale Sprachen, arbeiten mit Grammatiken einschließlich Backus-Naur-Form und Chomsky-Hierarchie, klassifizieren Automaten bis hin zu Turingmaschinen und lernen, wie Compiler und Interpreter Sprachen übersetzen. Sie erörtern die automatisierte Sprachverarbeitung.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb7-rechnernetze', 'Die Lernenden beschäftigen sich mit Topologien, Medien, Diensten und Vermittlungsverfahren, modellieren Netze in der Simulation und lernen Adressierung und Routing, Subnetting und VLANs, Namensauflösung, Authentifizierung, Transportverschlüsselung und Zertifikate kennen. Sie bauen ein Netzwerk aus Einplatinencomputern auf.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb8-informationssicherheit', 'Die Lernenden behandeln Schutzziele einschließlich der Zurechenbarkeit, beurteilen symmetrische und asymmetrische Verfahren wie AES und RSA und lernen Hashfunktionen, Blockchain, Signaturen, Datensicherung, Kryptoanalyse und Social Engineering kennen. Sie erörtern Grundsätze des Datenschutzes und den rechtlichen Rahmen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-lb9-datenmanagement', 'Die Lernenden behandeln Probleme des Datenmanagements in mehreren Anwendungsfeldern, den Lebenszyklus von Daten und die Beurteilung von Datenquellen auf Verzerrungen und Verlässlichkeit. Sie erstellen einen Datensatz, wenden das relationale Modell mit Normalisierung an, fragen mit SQL ab, visualisieren Daten, nutzen Austauschformate und APIs und beziehen Stellung zur Rolle von Daten in der Gesellschaft.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb1-betriebssysteme', 'Wahlbereich zu den Aufgaben eines Betriebssystems: Schichten, Ressourcenverwaltung, Prozesse und Threads, Datei- und Speicherverwaltung sowie Benutzerverwaltung. Die Lernenden arbeiten mit einem konkreten System und erörtern quelloffene und proprietäre Systeme.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb2-wirtschaftsinformatik', 'Wahlbereich zu Märkten und digitalen Gütern, Netzwerkökonomie (Skaleneffekte, Netzwerkeffekte, Plattformökonomie, Lock-in), typischen betrieblichen IT-Funktionen, der Kostenstruktur von Software und Finanzierungsmodellen wie Abonnements, Werbung und Open Source.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb3-informatik-und-oekologie', 'Ein Wahlbereich zum Energie- und Ressourcenverbrauch der Informatik, zu Green IT, zur Simulation ökologischer Modelle wie Klimamodellen, Wüstenausbreitung und Artenverlust, zu Reparierbarkeit, Wiederverwendung und Recycling sowie zur eigenen Nutzung digitaler Geräte durch die Lernenden.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb4-mathematische-methoden', 'Ein Wahlbereich zum Computer als Werkzeug der Mathematik: numerische Verfahren wie das Heron- und das Newton-Verfahren, Interpolation und Regression, Grenzen der numerischen Genauigkeit sowie automatische Beweissysteme und die Auswirkungen von KI auf Beweise.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/11-12/de-sn-lp-inf-inf-lk-wb5-generative-kunst', 'Ein Wahlbereich zur generativen Kunst: Entwicklungsumgebungen, geometrische Formen, zufällige Parameter, Rekursion und Fraktale, KI-Methoden sowie Fragen der Urheberschaft bei Werken, die Mensch und Maschine gemeinsam schaffen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb1-informationen-und-daten', 'Die Lernenden erhalten einen ersten Einblick in die Informatik und unterscheiden die Begriffe Information und Daten. Sie lernen Darstellungsformen, die binäre Codierung von Zahlen, Text und Bildern, Einheiten von Kilo bis Tera sowie objektorientierte Ideen am Beispiel von Vektorgrafiken und Office-Software kennen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb2-informatiksysteme', 'Die Lernenden lernen die Hardwarebausteine von Computergeräten kennen und wenden das EVA-Modell (Eingabe, Verarbeitung, Ausgabe) auf Systeme des Alltags an, nutzen dabei Zustandsdiagramme und benennen die Grenzen des Modells. Außerdem lernen sie Betriebssysteme, Dateitypen und sinnvolle Dateinamen kennen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-lb3-algorithmen', 'Die Lernenden beschreiben algorithmische Abläufe in Worten und lösen einfache Probleme in einer blockbasierten oder visuellen Programmierumgebung.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb1-rechnen-mit-binaerzahlen', 'Ein Wahlbereich zu den Grundoperationen mit Binärzahlen: Addition, Multiplikation und Schiebeoperationen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb2-computergrafik', 'Ein Wahlbereich zu Bildbearbeitungssoftware: Bildgröße und Zuschneiden, Farbkanäle, Graustufen und Negativbilder.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/7/de-sn-lp-inf-inf-k7-wb3-geschichte-der-rechentechnik', 'Ein Wahlbereich zu Meilensteinen der Geschichte der Rechentechnik von Schickard und Pascal bis zu Lovelace, Zuse, von Neumann und Turing, gegebenenfalls mit dem Besuch eines technischen Museums.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb1-algorithmen', 'Die Lernenden erfahren, was ein Verfahren zu einem Algorithmus macht, und prüfen dies an Alltagsbeispielen wie sozialen Medien oder In-App-Käufen. Sie lösen einfache Aufgaben in einer visuellen Programmierumgebung mit Sequenz, Verzweigung und Schleife und diskutieren die gesellschaftliche Rolle von Algorithmen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb2-vernetzte-systeme', 'Die Lernenden entwickeln Suchstrategien, nutzen Kommunikations- und Kooperationsdienste mit guten Umgangsformen und lernen Grundlagen des Datenschutzes und der Datensicherheit kennen (Phishing, Passwörter, Authentizität). Sie lernen außerdem, wie Netzwerkadressen aufgebaut sind, und beurteilen Informationsquellen, darunter manipulierte Bilder und generierte Texte.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-lb3-komplexaufgabe', 'Die Lernenden verbinden Inhalte der Klassenstufen 7 und 8 in einem Projekt, zum Beispiel einem fächerübergreifenden Projekt, einem mit einem Content-Management-System erstellten Wiki oder Blog oder der Einrichtung eines mobilen Geräts, und reflektieren ihre Arbeitsweise.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb1-verschluesselung-von-informationen', 'Ein Wahlbereich zu historischen Verschlüsselungsverfahren: Substitutionsverfahren wie Caesar und Vigenère sowie Transpositionsverfahren wie die Skytale- und Spaltenverschlüsselung.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb2-computer-im-alltag', 'Ein Wahlbereich, in dem die Lernenden Stellung dazu beziehen, wie sich die Computernutzung auf ihre eigene Persönlichkeit auswirkt. Behandelt werden Informationsquellen, Abhängigkeit, Cybermobbing und Cybergrooming sowie der Wandel der Arbeitswelt durch die Digitalisierung.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/8/de-sn-lp-inf-inf-k8-wb3-computerspiele', 'Ein Wahlbereich zu Spielmechaniken: Umsetzung eines Spiels mit Kollisionserkennung und computergesteuerten Gegnern sowie Diskussion der Suchtgefahr.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb1-informationen-und-daten', 'Die Lernenden lernen, was ein Datenbanksystem ist, entwerfen ein Datenmodell für einen kleinen Ausschnitt der Welt und setzen es um. Sie üben Abfragen (Einfügen, Ändern, Löschen, Verbund, Aggregation) und diskutieren Persönlichkeitsrechte sowie die Risiken zentraler Datenhaltung und von Big Data.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb2-kuenstliche-intelligenz', 'Die Lernenden verschaffen sich einen Überblick über Gebiete der Künstlichen Intelligenz wie Expertensysteme, Sprach- und Gesichtserkennung und autonomes Fahren. Sie lernen überwachtes, unüberwachtes und bestärkendes Lernen mit Software-Werkzeugen kennen und beurteilen, wie weit Ergebnisse angesichts von Daten und Modell vertrauenswürdig sind.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-lb3-netzwerke', 'Die Lernenden lernen, wie Netzwerke Daten übertragen: Netzwerktypen und Komponenten, Peer-to-Peer und Client-Server, Pakete, Protokolle wie TCP/IP und HTTPS sowie Adressierung mit DNS und Routing. Sie lernen außerdem symmetrische und asymmetrische Verschlüsselung kennen und diskutieren Informationssicherheit.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb1-inhaltsverwaltung', 'Ein Wahlbereich zu Content-Management-Systemen: die Trennung von Inhalt und Gestaltung, die zugrunde liegende Datenbank und Benutzerrollen.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb2-digitalisierung-von-daten', 'Ein Wahlbereich zu technischen Verfahren, Bilder, Text und Audio zu digitalisieren.'),
  ('saxony-curriculum-repository', 'DE-SN/informatik/gymnasium/2022-portal-edition-line-gymnasium-infor/9/de-sn-lp-inf-inf-k9-wb3-graphen', 'Ein Wahlbereich zur Modellierung von Problemen als Graphen: neuronale Netze, kürzeste Wege (Dijkstra), das Problem des Handlungsreisenden, die Modellierung von Zuständen und die Huffman-Codierung von Text.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/10/de-st-lp-bio-sjg10-evolution', 'Die Lernenden deuten biologische Phänomene auf der Grundlage der Evolution: Variation und Selektion als Mechanismus, Belege aus Fossilien und homologen Organen, die Verwandtschaft von Menschen und Menschenaffen sowie den Unterschied zwischen ultimaten und proximaten Erklärungen. Sie wägen außerdem wissenschaftliche gegen nichtwissenschaftliche Sichtweisen wie den Kreationismus ab.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/10/de-st-lp-bio-sjg10-vererbung', 'Die Lernenden erklären, wie Merkmale vererbt werden und wie Variation durch Rekombination, Mutation und Modifikation entsteht, und wenden die Mendelschen Regeln auf Züchtung und auf menschliche Merkmale an. Die Züchtung wird mit der Gentechnik verglichen, und ethische Fragen der Gentechnik werden diskutiert.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-dna-zum-merkmal', 'Die Lernenden behandeln den Aufbau der DNA, Replikation, Proteinbiosynthese, epigenetische Regulation, Telomere, Krebsgene, CRISPR/Cas9 und weitere Werkzeuge der Gentechnik sowie den genetischen Fingerabdruck. Sie vergleichen genetische und umweltbedingte Variation im Hinblick auf Biodiversität und Evolution und bewerten Anwendungen der Humangenetik.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-entstehung-biodiversitaet', 'Die Lernenden erklären den Artwandel mit der Synthetischen Evolutionstheorie, einschließlich Selektionsformen, Drift, Artbildung, Fitness und Verwandtenselektion, und prüfen Hypothesen zur Evolution des Menschen. Außerdem behandeln sie Klimaregeln, Antibiotikaresistenz, kulturelle Evolution, das Sozialverhalten von Primaten und die Beurteilung von Rassismus.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-reiz-reaktion-verhalten', 'Die Lernenden erklären, wie Neuronen, Synapsen und Rezeptoren Informationen verarbeiten, und betrachten Verhalten auf der proximaten Ebene. Sie behandeln dabei Reflexe, Schlüsselreize, Konditionierung und Lernen. Sucht, Stress und Hormone sind eingeschlossen, und es wird darauf geachtet, wie Verhaltensforschung angelegt wird.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-ean-umweltfaktor-oekosystem', 'Die Lernenden erklären, wie Umweltfaktoren das Vorkommen und die Anpassung von Organismen prägen, modellieren Populationswachstum (exponentielles und logistisches Wachstum, r- und K-Strategien, Lotka-Volterra-Regeln) und die Koexistenz von Arten über die Nische. Eine Exkursion in ein Ökosystem und Simulationen von Wechselwirkungen zwischen Populationen gehören dazu.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-dna-zum-merkmal', 'Die Lernenden verknüpfen DNA-Aufbau, Replikation und Proteinbiosynthese mit Merkmalen, vergleichen genetische und umweltbedingte Variation im Licht von Biodiversität und Evolution und analysieren Vererbung mit Stammbäumen und Kreuzungen. Gentests, Gentherapie und Stammzellen werden anhand ethischer Kriterien diskutiert.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-entstehung-biodiversitaet', 'Die Lernenden erklären Entstehung und Wandel von Arten mit der Synthetischen Evolutionstheorie: Genpool, Selektionsformen, Drift, Artbildung, Stammbäume, Fitness und Verwandtenselektion. Sie untersuchen Belege und die Frage, wie Wissen über den Anpassungswert von Verhalten gewonnen wird.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/11-12/de-st-lp-bio-sjg11-12-gan-umweltfaktor-oekosystem', 'Die Lernenden erklären, wie zusammenwirkende Umweltfaktoren bestimmen, wo Organismen vorkommen und wie gut sie angepasst sind, anhand von Toleranzbereich, ökologischer Nische und Beziehungen zwischen Arten. Wasserhaushalt und Photosynthese der Pflanzen, Stoffkreisläufe und der Schutz der Biodiversität werden ebenfalls behandelt.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/5-6/de-st-lp-bio-sjg5-6-angepasstheit-wirbeltiere', 'Die Lernenden vergleichen, wie der Körperbau von Wirbeltieren zu Lebensweise und Lebensraum passt, ordnen Tiere anhand typischer Merkmale den Wirbeltierklassen zu und verfolgen die Verwandtschaft zwischen zwei Klassen. Modellexperimente und Sektion (praktisch oder am Bildschirm) sind verpflichtend.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/7-8/de-st-lp-bio-sjg7-8-angepasstheit-wirbellose', 'Die Lernenden erklären die Vielfalt der wirbellosen Tiere als Ergebnis der Anpassung an Lebensweise und Lebensraum, ordnen Tiere anhand ihrer Merkmale Gruppen zu und bringen das Populationswachstum von Insekten mit Umweltbedingungen in Verbindung. Einfache Verhaltensexperimente und eine Exkursion gehören dazu.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/9/de-st-lp-bio-sjg9-mensch-umwelt-reiz-verhalten', 'Die Lernenden verknüpfen Reiz und Reaktion bei Organismen, vergleichen Nervensysteme und Sinnesorgane und führen Verhaltensexperimente durch, unter anderem um Verhalten als angepasst an die Umstände zu erklären. Die Funktion des menschlichen Gehirns, Sucht, Stress und die Verbindung von Nerven- und Hormonsystem runden die Einheit ab.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/biologie/gymnasium/stand-01-08-2022-in-kraft-seit-2016-anpa/9/de-st-lp-bio-sjg9-oekosystem-wald', 'Die Lernenden beschreiben das Ökosystem Wald: biotische und abiotische Faktoren, Toleranzbereiche, Anpassung der Pflanzen an das Licht und der Tiere an die Temperatur, Beziehungen zwischen Arten, Populationen und Nahrungsnetze. Sie bewerten den Einfluss des Menschen, invasive Arten und Nachhaltigkeit.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/10/de-st-lp-inf-sjg10-algorithmen-datenstrukturen-implementieren', 'Die Lernenden implementieren und testen Klassen, Objekte und Methoden in einer textbasierten Programmiersprache, verwenden Datentypen und Variablen und bearbeiten ein Such-, Sortier- oder Verschlüsselungsverfahren als Problemlösezyklus. UML-Klassendiagramme und Fehlerbehandlung werden eingeführt.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/10/de-st-lp-inf-sjg10-grundlagen-informatiksysteme', 'Die Lernenden schreiben Regeln für einfache formale Sprachen und bauen Akzeptoren, unterscheiden formale von natürlichen Sprachen und lernen, wie TCP/IP-Netze mit Schichten, Protokollen und Adressierung funktionieren. Sie modellieren und simulieren Heim- oder Schulnetzwerke mit Sicherheitsmaßnahmen und reflektieren die Grenzen automatisierter Systeme.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs1-objektorientiertes-modellieren', 'Die Lernenden analysieren Probleme mit Anwendungsfalldiagrammen, leiten Klassen und Beziehungen für einen objektorientierten Entwurf ab und setzen sie in einer Programmiersprache um, einschließlich Vererbung, dynamischer Datenstrukturen und Dateispeicherung. Mögliche Projekte sind Simulationen, Spiele oder verteilte Anwendungen.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs2-daten-erfassen-strukturieren', 'Die Lernenden entwerfen relationale Datenbanken mit Entity-Relationship-Modellen, überführen sie in relationale Schemata bis zur dritten Normalform und fragen Daten mit einer Abfragesprache ab. Außerdem wägen sie den rechtmäßigen Umgang mit Daten ab und vergleichen die Datenbankmodellierung mit der objektorientierten Modellierung.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs3-software-engineering-projektarbeit', 'Die Lernenden führen in einem Team ein Softwareprojekt durch: Analyse, Spezifikation, Entwurf, Implementierung, Test und Qualitätssicherung. Sie planen und dokumentieren die Arbeit, stimmen sich mit einem Auftraggeber ab und begründen Entscheidungen zu Algorithmen, Datenhaltung und Nachhaltigkeit.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/11-12/de-st-lp-inf-sjg11-12-kurs4-aktuelle-entwicklungen-gesellschaft', 'Die Lernenden untersuchen aktuelle Entwicklungen der Informatik und ihre Auswirkungen auf Gesellschaft und Umwelt und wählen Themen wie künstliche Intelligenz, soziale Netzwerke, virtuelle Welten oder den Ressourcenverbrauch von Geräten. Sie beurteilen Chancen, Risiken und Nachhaltigkeit und können ein kleines KI-System bauen oder trainieren.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/9/de-st-lp-inf-sjg9-algorithmen-interpretieren-entwickeln', 'Die Lernenden formulieren Verfahren, entwerfen und testen Algorithmen aus Grundbausteinen in einer visuellen Programmiersprache und modellieren zustandsbasierte Systeme als endliche Automaten. Sie diskutieren Einsatz, Risiken und Ressourcenbedarf von Algorithmen im Alltag.'),
  ('saxony-anhalt-curriculum-repository', 'DE-ST/informatik/gymnasium/01-08-2022-in-kraft-seit-2017-anpassung/9/de-st-lp-inf-sjg9-daten-codieren-verarbeitung', 'Die Lernenden bilden Informationen auf Daten ab, arbeiten mit Einheiten und Zahlensystemen und analysieren die Funktionsweise von Computern nach dem EVA-Prinzip und dem Von-Neumann-Modell. Sie befassen sich mit Dateiformaten, Betriebssystemen, Netzwerken, logischen Gattern und der Nachhaltigkeit von Geräten.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-grosse-datenmengen', 'Die Lernenden erfahren, wie große Datenmengen automatisch erfasst werden, zum Beispiel durch Sensoren oder Tracking, und für die Auswertung aufbereitet werden. Sie schreiben Programme, die solche Daten speichern, auswerten und visualisieren, und diskutieren, wie aussagekräftig und wie manipulierbar die Ergebnisse sind.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-netzwerke-internet', 'Die Lernenden erklären, wie lokale und globale Netzwerke aufgebaut sind und wie Daten darin übertragen werden, einschließlich Adressierung und Routing, Client-Server-Modell und Namensauflösung. Sie modellieren ein einfaches Netzwerk virtuell und vergleichen Sicherheitsmaßnahmen wie Firewalls.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/10/de-th-lp-inf-mbi-10-spielwelten', 'Die Lernenden analysieren digitale Spiele, vor allem Mobile Games, als Teil der Jugendkultur, darunter Spielprinzipien, Monetarisierungsmechanismen wie Lootboxen und Altersfreigaben. Sie modellieren außerdem ein einfaches Spiel, setzen es in einer grafischen Programmierumgebung um und beziehen Stellung zu Stereotypen.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-maschinelles-lernen', 'Die Lernenden beschreiben Grundideen der KI wie Mustererkennung und maschinelles Lernen, typische Anwendungen und die Rolle der KI bei der Analyse großer Datenmengen. Sie setzen KI-Werkzeuge sorgfältig ein und erörtern ethische und rechtliche Fragen. Auf erhöhtem Niveau kommen die wichtigsten Lernarten, die Qualität von Trainingsdaten und das Training eines Modells hinzu.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-netzwerke-it-sicherheit', 'Die Lernenden beschreiben, wie Daten durch Netzwerke gelangen, einschließlich Client-Server-Modell, Schichten und Routing, und erklären Kompression, Verschlüsselung und Angriffe auf Chiffren. Sie führen ein Teamprojekt durch, implementieren eine symmetrische Verschlüsselung und diskutieren den Datenschutz. Auf erhöhtem Niveau kommt die asymmetrische Verschlüsselung hinzu.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-praktische-informatik', 'Die Lernenden entwerfen, implementieren und vergleichen iterative und rekursive Algorithmen und modellieren einfache Situationen objektorientiert. Sie wenden Verfahren wie Backtracking und Teile-und-herrsche an. Auf erhöhtem Niveau kommen dynamische Datenstrukturen, Graphen und Polymorphie hinzu.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-technische-informatik', 'Die Lernenden erklären die Von-Neumann-Architektur, die binäre Codierung und das binäre Rechnen sowie logische Gatter mit Wahrheitstabellen, einschließlich Flipflops und Addierern. Auf erhöhtem Niveau kommen gebrochene Zahlen in Bitmustern, Addierschaltungen und Analog-Digital-Wandler hinzu.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-theoretische-informatik', 'Die Lernenden vergleichen natürliche und formale Sprachen, leiten Wörter mit Grammatiken ab und erklären endliche Automaten und das Halteproblem. Auf erhöhtem Niveau kommen Turingmaschinen, Grenzen der Berechenbarkeit, Komplexitätsklassen und die O-Notation hinzu.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/11-12/de-th-lp-inf-inf-11-12-wissensbasierte-systeme', 'Die Lernenden modellieren einen abgeschlossenen Weltausschnitt als Fakten und Regeln, setzen ihn in einem geeigneten System um und fragen ihn ab. Sie beschreiben ein wissensbasiertes System als Datenbasis, Regelwerk und Inferenzmaschine, einschließlich Tiefensuche und Backtracking, und beurteilen seine Grenzen sowie den Gedanken der schwachen KI.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-algorithmische-grundkonzepte', 'Die Lernenden beschreiben Algorithmen aus dem Alltag und verwenden grundlegende Bausteine wie Sequenzen und Schleifen in einer grafischen Programmierumgebung. Sie erstellen und testen einfache Programme in Partnerarbeit, analysieren Fehler und stellen eigene Projektideen vor.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-bilder-bearbeiten', 'Die Lernenden erfahren, wie Rasterbilder mit dem RGB-Farbmodell als Binärdaten gespeichert werden und wie Auflösung und Farbtiefe den Speicherbedarf beeinflussen. Sie wandeln zwischen Bildern und Bitfolgen um, bearbeiten Bilder mit Werkzeugen und erörtern, wie schwer manipulierte Bilder zu erkennen sind.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-informatiksysteme', 'Die Lernenden erkennen Informatiksysteme in ihrer Umgebung und beschreiben mithilfe des EVA-Prinzips Hardware, Software und Netzwerke und ihr Zusammenwirken. Sie orientieren sich auf Benutzeroberflächen, verwalten Dateien und Ordner und nutzen webbasierte Lernplattformen.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-kommunizieren', 'Die Lernenden vergleichen digitale Kommunikation mit der Kommunikation von Angesicht zu Angesicht, benennen Risiken wie Cybermobbing und Cybergrooming und lernen Grundlagen des Datenschutzes für Kommunikationswerkzeuge kennen. Sie wenden Datenschutzeinstellungen an, reflektieren ihr eigenes Verhalten und vereinbaren Regeln für einen respektvollen Austausch im Netz.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-medienalltag-reflektieren', 'Die Lernenden beschreiben die Medienarten, denen sie täglich begegnen, und wofür sie jeweils genutzt werden. Sie dokumentieren und reflektieren ihre eigene Nutzung und deren Beweggründe und wägen Nutzen und Risiken wie Bildschirmzeit und Kosten ab. Daraus leiten sie sinnvolle Regeln für den eigenen Mediengebrauch ab.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-praesentationen-gestalten', 'Die Lernenden gestalten digitale Präsentationen für ein vorgegebenes Publikum mit aussagekräftigen Bildern, kurzem Text und einheitlichem Layout. Sie beachten das Urheberrecht, zitieren Quellen, exportieren und teilen das Ergebnis und bewerten Präsentationen anhand vorgegebener Kriterien.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-suchen-recherchieren-i', 'Die Lernenden erfahren, wie Suchumgebungen funktionieren, zum Beispiel Indexierung und Ranking, vergleichen sie und nutzen Suchoperatoren und Filter. Sie beurteilen Ergebnisse nach Relevanz und Verlässlichkeit, geben Quellen korrekt an und überlegen, welche Absichten hinter Medienangeboten stehen.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/5-6/de-th-lp-inf-mbi-5-6-texte-strukturieren-i', 'Die Lernenden nutzen die Grundfunktionen eines Textverarbeitungsprogramms, um übersichtliche, gut formatierte Dokumente mit Formatvorlagen und Korrekturwerkzeugen zu erstellen. Sie behandeln Textelemente als Objekte mit Eigenschaften, beachten Zitierregeln und überarbeiten eigene und gemeinsame Texte.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-datenbanken', 'Die Lernenden entwerfen für eine Situation wie ein soziales Netzwerk ein Entity-Relationship-Datenmodell, setzen es in einem Datenbanksystem um und führen grundlegende Operationen und Abfragen aus. Sie verknüpfen dies mit der Datenerhebung von Plattformen und reflektieren Datenschutz und ihre eigenen Datenspuren.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-digitale-inhalte-veroeffentlichen', 'Die Lernenden planen und erstellen ein digitales Medienprodukt wie einen Podcast oder ein Video und erklären technische Aspekte wie Dateiformate und Kompression. Sie erörtern Urheberrecht, Privatsphäre und die ethischen Folgen der Veröffentlichung von Inhalten für unterschiedliche Zielgruppen.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-eingebettete-systeme', 'Die Lernenden erfahren, wie Sensoren Daten erfassen und Aktoren auf die Umgebung einwirken, und konfigurieren und programmieren einen Mikrocontroller oder Roboter für eine Aufgabe. Sie zerlegen Probleme in Teilprobleme, testen ihre Lösungen und beheben Fehler, planen Teamprojekte und diskutieren Automatisierung in Smart Homes und in der Industrie.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-social-media', 'Die Lernenden beschreiben, wie soziale Medien funktionieren, zum Beispiel nutzergenerierte Inhalte und algorithmische Steuerung, und wägen Chancen und Risiken ab. Sie erklären datengetriebene Geschäftsmodelle und die Rolle von Influencern und reflektieren ihre eigenen Online-Profile und ihre Privatsphäre.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-suchen-recherchieren-ii-ki', 'Die Lernenden erklären, wie Algorithmen Suchergebnisse filtern und personalisieren und warum Metadaten und Tracking von Bedeutung sind. Sie beschreiben, wie generative KI-Modelle wie große Sprachmodelle arbeiten und wo sie an Grenzen stoßen, prüfen maschinell erzeugte Inhalte auf Glaubwürdigkeit und reflektieren Verzerrungen.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/7-8/de-th-lp-inf-mbi-7-8-tabellenkalkulation', 'Die Lernenden erfassen Alltagsdaten in geeigneten Datentypen, nutzen Zelladressierung und grundlegende Funktionen und erstellen Tabellenkalkulationsmodelle für Alltagsprobleme. Sie wählen Diagramme aus und begründen ihre Wahl und diskutieren, wie Daten manipuliert werden können.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/9/de-th-lp-inf-mbi-9-meinungsbildung-medienwelten', 'Die Lernenden untersuchen, wie digitale Medien die Meinungsbildung prägen, darunter Desinformation, durch Personalisierung entstehende Filterblasen und der Einfluss großer Plattformen. Sie betrachten KI-erzeugte Deepfakes, analysieren politische Medienformate und erstellen ein eigenes Medienprodukt zu einem gesellschaftlichen Thema.'),
  ('thuringia-curriculum-repository', 'DE-TH/informatik/gymnasium/2026-erprobungsfassung-two-separate-lehr/9/de-th-lp-inf-mbi-9-texte-strukturieren-ii', 'Die Lernenden erstellen komplexe, multimediale Dokumente mit Vorlagen und Formatvorlagen, nutzen automatische Funktionen wie Fußnoten und Inhaltsverzeichnisse und arbeiten gemeinsam daran. Sie probieren KI-gestützte Schreibfunktionen aus und reflektieren die Wirkung auf das eigene Schreiben, das Urheberrecht und den Ressourcenverbrauch.')
) AS v(project_slug, node_key, summary_de)
JOIN projects p ON p.slug = v.project_slug
WHERE n.project_id = p.id AND n.node_key = v.node_key AND n.summary_de IS NULL;

DO $$
DECLARE missing integer;
BEGIN
  SELECT count(*) INTO missing FROM curriculum_repository_structure_nodes n JOIN projects p ON p.id = n.project_id
  WHERE n.level = 'unit' AND n.summary_en IS NOT NULL AND n.summary_de IS NULL
    AND p.slug IN ('germany-curriculum-repository', 'saxony-curriculum-repository', 'saxony-anhalt-curriculum-repository', 'thuringia-curriculum-repository');
  IF missing <> 0 THEN
    RAISE EXCEPTION 'migration 223: % unit nodes of the German repositories still have no German summary', missing;
  END IF;
END $$;
